<?php
namespace App\Http\Controllers;
use App\Models\AppSetting; use Illuminate\Http\Request; use Illuminate\Support\Facades\Storage;
class SettingsController extends Controller { public function edit(){return view('settings.edit',['settings'=>['site_name'=>AppSetting::value('site_name','Festiva'),'logo'=>AppSetting::value('logo'),'currency_symbol'=>AppSetting::value('currency_symbol','₹'),'pdf_footer'=>AppSetting::value('pdf_footer')]]);} public function update(Request $request){$data=$request->validate(['site_name'=>'required|string|max:100','currency_symbol'=>'required|string|max:10','pdf_footer'=>'nullable|string|max:500','logo'=>'nullable|image|mimes:jpg,jpeg,png,webp|max:2048']); foreach(['site_name','currency_symbol','pdf_footer'] as $key){AppSetting::updateOrCreate(['key'=>$key],['value'=>$data[$key] ?? null]);} if($request->hasFile('logo')){$old=AppSetting::value('logo'); if($old) Storage::disk('public')->delete($old); $path=$request->file('logo')->store('branding','public'); AppSetting::updateOrCreate(['key'=>'logo'],['value'=>$path]);} return back()->with('success','Brand settings saved.');} }
